    <*> fieldInt "since" kv
    <*> fieldList "rc" kv
    <*> fieldList "seat" kv
    <*> fieldStr "model" kv

encodeMainRecord :: MainRecord -> Fields
encodeMainRecord r =
  [ ("main", encList (mainRecordMain r))
  , ("path", encStr (mainRecordPath r))
  , ("head", encOpt (mainRecordHead r))
  , ("status", encBool (mainRecordStatus r))
  , ("since", encInt (mainRecordSince r))
  , ("rc", encList (mainRecordRc r))
  , ("seat", encList (mainRecordSeat r))
  , ("model", encStr (mainRecordModel r))
  ]

